import React, { useState, useEffect } from "react";
import { useLocation } from "react-router-dom";
import axiosInstance from "../api/AxiosConfig";
import { Card, Button } from "react-bootstrap";

const CertDB_ProductInfo = () => {
  const location = useLocation();
  const [product, setProduct] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const productId = location.state?.productId;
    if (productId) {
      fetchProductDetails(productId);
    }
  }, [location]);

  const fetchProductDetails = async (productId) => {
    try {
      const response = await axiosInstance.get(`/product/${productId}`);
      setProduct(response.data);
      setLoading(false);
    } catch (error) {
      console.error("Error fetching product details:", error);
      setLoading(false);
    }
  };

  if (loading) {
    return <div className="text-center">Loading...</div>;
  }

  if (!product) {
    return <div className="text-center">Product not found</div>;
  }

  return (
    <div className="row">
      <div className="col-md-12 grid-margin stretch-card">
        <div className="card">
          <div className="card-body">
            <h4 className="card-title">Product Information</h4>
            <div className="row">
              <div className="col-md-6">
                <Card className="mb-4">
                  <Card.Body>
                    <h5 className="card-title">Basic Information</h5>
                    <div className="mb-3">
                      <strong>Product ID:</strong> {product.productId}
                    </div>
                    <div className="mb-3">
                      <strong>Product Name:</strong> {product.companyName}
                    </div>
                    <div className="mb-3">
                      <strong>Product Manager:</strong> {product.productManager}
                    </div>
                    <div className="mb-3">
                      <strong>Comments:</strong> {product.comments}
                    </div>
                    <div className="mb-3">
                      <strong>Photos:</strong> {product.photos}
                    </div>
                  </Card.Body>
                </Card>
              </div>
              <div className="col-md-6">
                <Card className="mb-4">
                  <Card.Body>
                    <h5 className="card-title">Status Information</h5>
                    <div className="mb-3">
                      <strong>Status:</strong>{" "}
                      <span className="badge bg-success">Active</span>
                    </div>
                    <div className="mb-3">
                      <strong>Last Updated:</strong>{" "}
                      {new Date().toLocaleDateString()}
                    </div>
                  </Card.Body>
                </Card>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CertDB_ProductInfo;
